insert into validation_results values ('repeat_import', maim.reconcile_asset_catalog_manifest('10000000-0000-0000-0000-000000000001','[{"stable_id":"MAIM-CD-TEST-ONE","sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","size_bytes":12,"format":".png","original_filename":"safe.png","project_code":"00","project":"MAIM 00 Brand System","project_relative_path":"  assets/safe.png","drive_file_id":"driveTestAsset001","drive_url":"https://drive.google.com/file/d/driveTestAsset001/view","upload_status":"uploaded","integrity_status":"sha256_verified","dependencies":[{"dependency":"font.woff2","status":"unresolved","blocks_preview":true}]}]'::jsonb));
